import React, { useState, useEffect } from "react";
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";
import { API } from "../utils";
import { motion } from "framer-motion";
import "animate.css";
import {
  FaTooth,
  FaCalendarAlt,
  FaMoneyBillWave,
  FaPills,
  FaCheckCircle,
} from "react-icons/fa";
import "../styles/main.css";

const Struk = () => {
  const { id_struk } = useParams();
  const [struk, setStruk] = useState(null);
  const [error, setError] = useState(null);
  const [msg, setMsg] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    if (id_struk) {
      fetchStruk();
    }
  }, [id_struk]);

  const fetchStruk = async () => {
    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        setMsg("Silakan login terlebih dahulu.");
        return;
      }
      const res = await API.get(`/pasien/periksa/struk/${id_struk}`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
        withCredentials: true,
      });
      setStruk(res.data);
      setError(null);
    } catch (error) {
      console.error("Error fetching struk data:", error);
      setError("Gagal memuat struk. Coba lagi nanti.");
    }
  };

  const handleSelesai = async () => {
    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        setMsg("Silakan login terlebih dahulu.");
        return;
      }
      await API.put(
        `/struk/${id_struk}`,
        { status: "Selesai" },
        {
          headers: { Authorization: `Bearer ${token}` },
          withCredentials: true,
        }
      );
      navigate("/historypasien");
    } catch (error) {
      console.error("Gagal menyelesaikan struk:", error);
    }
  };

  return (
    <div className="columns is-centered mt-6 animate__animated animate__fadeIn">
      <div className="column is-half">
        {error && <div className="notification is-danger">{error}</div>}
        {struk ? (
          <motion.div
            className="box p-5"
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
          >
            <h1 className="title has-text-centered mb-5">
              <FaTooth className="mr-2" style={{ color: "#00d1b2" }} />
              Struk Pemeriksaan
            </h1>
            <div className="content">
              <p>
                <strong>👤 Nama Pasien:</strong> {struk?.pasien?.nama}
              </p>
              <p>
                <strong>
                  <FaCalendarAlt className="mr-1" /> Tanggal Periksa:
                </strong>{" "}
                {struk?.periksa?.tanggal_periksa}
              </p>
              <p>
                <strong>
                  <FaMoneyBillWave className="mr-1" /> Biaya Periksa:
                </strong>{" "}
                Rp{struk?.periksa?.biaya_periksa?.toLocaleString()}
              </p>
              <p>
                <strong>
                  <FaPills className="mr-1" /> Obat:
                </strong>{" "}
                {struk?.obat?.nama_obat}
              </p>
              <p>
                <strong>💊 Harga Obat:</strong> Rp{struk?.obat?.harga?.toLocaleString()}
              </p>
              <p className="has-text-weight-bold">
                <FaMoneyBillWave className="mr-1" />
                Total Biaya: Rp{struk?.total_biaya?.toLocaleString()}
              </p>
            </div>

            {struk.status !== "Selesai" && (
              <motion.button
                className="button is-primary mt-3 is-fullwidth"
                onClick={handleSelesai}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                <FaCheckCircle className="mr-2" />
                Tandai Selesai
              </motion.button>
            )}
          </motion.div>
        ) : (
          <div className="has-text-centered">
            <span className="is-size-5 animate__animated animate__pulse animate__infinite">
              Memuat data struk...
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

export default Struk;
